import json, os, re

W = "/Users/kristinarash/Library/Caches/sportsci-batch-97"
tax = json.load(open(os.path.join(W, "taxonomy.json"), encoding="utf-8"))
inputs = {x["id"]: x for x in json.load(open(os.path.join(W, "inputs.json"), encoding="utf-8"))}

for qid in ["Q41", "Q42", "Q43", "Q44", "Q45", "Q46", "Q47", "Q48"]:
    path = os.path.join(W, "drafts", qid + ".json")
    d = json.load(open(path, encoding="utf-8"))
    problems = []
    if d["sourceFile"] != inputs[qid]["sourceFile"]:
        problems.append("sourceFile mismatch")
    if d["id"] != qid:
        problems.append("id mismatch")
    if d["decision"] not in ("INCLUDE", "EXCLUDE", "DEGRADED"):
        problems.append("bad decision")
    if d["decision"] == "EXCLUDE" and not d["exclusionReason"]:
        problems.append("missing exclusionReason")
    if d["decision"] == "DEGRADED" and not d["degradedReason"]:
        problems.append("missing degradedReason")
    if d["decision"] != "EXCLUDE":
        for key, vocab in [("domains", "domains"), ("audiences", "audiences"), ("sports", "sports"), ("populations", "populations")]:
            for v in d[key]:
                if v not in tax[vocab]:
                    problems.append("bad %s value: %s" % (key, v))
        if d["studyDesign"] not in tax["studyDesigns"]:
            problems.append("bad studyDesign")
        if d["primaryDomain"] not in tax["domains"]:
            problems.append("bad primaryDomain")
        if d["primaryDomain"] not in d["domains"]:
            problems.append("primaryDomain not in domains")
        p = d["paper"]
        for k in ["year", "citation", "doi", "abstract", "tldr", "methods", "findings", "limitations", "practicalImplications", "athleteDev", "rtp"]:
            if p.get(k) in (None, ""):
                if not (k == "doi" and d.get("doiMissing")):
                    problems.append("paper." + k + " empty")
        for k in ["abstract", "tldr", "methods", "findings", "limitations", "practicalImplications", "athleteDev", "rtp", "evidenceSummary", "screeningLimitations", "synthesisCaution"]:
            v = p.get(k) if k in p else d.get(k)
            if v and ("—" in v or "–" in v):
                problems.append("dash in " + k)
    for k in ["identityCheck", "confidence"]:
        if not d.get(k):
            problems.append("missing " + k)
    if "—" in json.dumps(d, ensure_ascii=False):
        problems.append("em dash somewhere")
    print(qid, d["decision"], "OK" if not problems else problems)

